create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists (select 1 from public.admin_profiles where user_id=auth.uid() and active=true) $$; revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to authenticated;
create or replace function public.update_booking_status(p_booking_id uuid,p_status text) returns table (booking_id uuid,status text) language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'authorization denied'; end if; if p_status not in ('pending','confirmed','cancelled','expired','refunded') then raise exception 'invalid booking status'; end if; update public.bookings set status=p_status,confirmed_at=case when p_status='confirmed' then coalesce(confirmed_at,now()) else confirmed_at end where id=p_booking_id; if not found then raise exception 'booking not found'; end if; return query select p_booking_id,p_status; end; $$; revoke all on function public.update_booking_status(uuid,text) from public; grant execute on function public.update_booking_status(uuid,text) to authenticated;
create or replace function public.log_admin_action(p_action text,p_target_type text,p_target_id text default null,p_metadata jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; begin if auth.uid() is null or not public.is_admin() then raise exception 'authorization denied'; end if; insert into public.audit_logs(actor_id,action,target_type,target_id,metadata) values(auth.uid(),left(btrim(p_action),100),left(btrim(p_target_type),100),nullif(left(btrim(coalesce(p_target_id,'')),200),''),coalesce(p_metadata,'{}'::jsonb)) returning id into v_id; return v_id; end; $$; revoke all on function public.log_admin_action(text,text,text,jsonb) from public; grant execute on function public.log_admin_action(text,text,text,jsonb) to authenticated;